1	"use client";
2	
3	// Öffentlicher Ersparnis-Rechner Energiegemeinschaft Österreich (WP6). Reine Funktion eg/interesse.js rechnerOeffentlich
4	// (= Python eg_portal_kern.rechner_oeffentlich, API POST /api/eg/rechner): Netzentgelt aus der Regeltabelle (SNE-V 2018 bis
5	// Ende 2026, Arbeitshypothese ab 2027), Abgabenbefreiung nur EEG, Standardpreise aus src/lib/invest/markt.js.
6	
7	import { useMemo, useState } from "react";
8	import { AlertTriangle, Info, Leaf, PiggyBank, Sun, Users, Zap } from "lucide-react";
9	import Button from "@/components/ui/Button";
10	import { Auswahl, Gruppe, Kennzahl, Regler, Zahl } from "@/components/Rechner/bausteine";
11	import { ErgebnisKopf, Hinweis, MobilKurz, RechnerRahmen } from "@/components/Rechner/InvestTeile";
12	import { RECHNER_DECKUNG, RECHNER_MODELLE, RECHNER_PROFILE, RECHNER_ROLLEN, RECHNER_STANDARD, rechnerOeffentlich } from "@/lib/plattform/eg/interesse";
13	import { fmt } from "@/lib/rechner/annahmen";
14	
15	const opt = (o) => Object.entries(o).map(([id, x]) => ({ id, label: typeof x === "string" ? x : x.label, sub: typeof x === "string" ? undefined : x.sub }));
16	const euro = (v) => `${v < 0 ? "−" : ""}${fmt(Math.abs(Math.round(v)))} €`;
17	
18	export default function ErsparnisRechner({ ctaHref = "/registrieren?rolle=mitglied&weiter=%2Fportal%2Feg%2Fbeitritt" }) {
19	  const [e, setE] = useState({ ...RECHNER_STANDARD });
20	  const set = (k) => (v) => setE((a) => ({ ...a, [k]: v }));
21	  const r = useMemo(() => rechnerOeffentlich(e), [e]);
22	  const verbraucht = e.rolle !== "erzeuger";
23	  const erzeugt = e.rolle !== "verbraucher";
24	  const max = Math.max(1, ...r.teile.map((t) => Math.abs(t.eur)));
25	  return (
26	    <RechnerRahmen
27	      mitlaufend
28	      eingaben={
29	        <>
30	          <MobilKurz werte={[["Vorteil netto", euro(r.nettoEur)], ["aus Gemeinschaft", `${fmt(r.quotePct)} %`], ["CO₂", `${fmt(r.co2Kg)} kg`]]} />
31	          <div className="space-y-8">
32	            <Gruppe titel="Sie">
33	              <Auswahl legende="Rolle" wert={e.rolle} onChange={set("rolle")} optionen={opt(RECHNER_ROLLEN)} klein />
34	              {verbraucht && <Auswahl legende="Verbrauch" wert={e.profil} onChange={set("profil")} optionen={opt(RECHNER_PROFILE)} spalten={2} klein />}
35	              {verbraucht && <Regler label="Jahresverbrauch" wert={e.verbrauchKwh} min={500} max={60000} step={100} format={(v) => `${fmt(v)} kWh`} onChange={set("verbrauchKwh")} hinweis="steht auf Ihrer Jahresabrechnung" />}
36	              {erzeugt && <Regler label="PV-Anlage" wert={e.kwp} min={1} max={500} step={0.5} stellen={1} format={(v) => `${fmt(v, 1)} kWp`} onChange={set("kwp")} hinweis={`≈ ${fmt(r.erzeugungKwh)} kWh Erzeugung pro Jahr`} />}
37	              {erzeugt && <Regler label="Eigenverbrauch im Haus" wert={e.eigenverbrauchPct} min={0} max={90} step={5} format={(v) => `${fmt(v)} %`} onChange={set("eigenverbrauchPct")} />}
38	            </Gruppe>
39	            <Gruppe titel="Gemeinschaft">
40	              <Auswahl legende="Modell" wert={e.modell} onChange={set("modell")} optionen={opt(RECHNER_MODELLE)} spalten={2} klein />
41	              <Auswahl legende="Erzeugung in der Gemeinschaft" wert={e.deckung} onChange={set("deckung")} optionen={opt(RECHNER_DECKUNG)} klein />
42	              <Auswahl legende="Netzentgelt-Regeln" wert={String(e.jahr)} onChange={(v) => set("jahr")(Number(v))} optionen={[{ id: "2026", label: "2026", sub: "SNE-V 2018" }, { id: "2027", label: "ab 2027", sub: "Arbeitshypothese" }]} klein />
43	            </Gruppe>
44	            <Gruppe titel="Preise netto (ct/kWh)">
45	              {verbraucht && <Regler label="Energiepreis Ihres Lieferanten" wert={e.lieferantCt} min={5} max={30} step={0.5} stellen={1} format={(v) => `${fmt(v, 1)} ct`} onChange={set("lieferantCt")} hinweis="nur Energieanteil, ohne Netz und Abgaben" />}
46	              {verbraucht && <Regler label="Preis in der Gemeinschaft" wert={e.gemeinschaftCt} min={3} max={25} step={0.5} stellen={1} format={(v) => `${fmt(v, 1)} ct`} onChange={set("gemeinschaftCt")} hinweis="üblich 9–14 ct (Marktbeobachtung)" />}
47	              {verbraucht && <Regler label="Netznutzungs-Arbeitspreis" wert={e.netzApCt} min={2} max={12} step={0.1} stellen={1} format={(v) => `${fmt(v, 1)} ct`} onChange={set("netzApCt")} hinweis="je Netzgebiet verschieden, siehe Netzrechnung" />}
48	              {erzeugt && <Regler label="Einspeisepreis der Gemeinschaft" wert={e.einspeiseEgCt} min={2} max={15} step={0.5} stellen={1} format={(v) => `${fmt(v, 1)} ct`} onChange={set("einspeiseEgCt")} />}
49	              {erzeugt && <Regler label="Alternative: Marktpreis Überschuss" wert={e.marktCt} min={0} max={15} step={0.5} stellen={1} format={(v) => `${fmt(v, 1)} ct`} onChange={set("marktCt")} />}
50	              <Regler label="Gebühren und Beitrag" wert={e.gebuehrenJahr} min={0} max={150} step={5} format={(v) => `${fmt(v)} €/Jahr`} onChange={set("gebuehrenJahr")} />
51	            </Gruppe>
52	          </div>
53	        </>
54	      }
55	      ergebnis={
56	        <>
57	          <p className="sr-only" aria-live="polite">{`Vorteil netto ${Math.round(r.nettoEur)} Euro pro Jahr, ${r.quotePct} Prozent Ihres Verbrauchs aus der Gemeinschaft.`}</p>
58	          <ErgebnisKopf titel="Ihr Vorteil pro Jahr" plakette={`${RECHNER_MODELLE[e.modell].label} · ${e.jahr === 2027 ? "ab 2027" : "2026"}`} />
59	          <div className="mt-5 grid grid-cols-2 gap-3 xl:grid-cols-4">
60	            <Kennzahl ton="gruen" icon={PiggyBank} label="Vorteil netto" zusatz={`nach ${fmt(r.gebuehrenEur)} € Gebühren`}><Zahl wert={r.nettoEur} suffix=" €" /></Kennzahl>
61	            <Kennzahl ton="navy" icon={Users} label="Aus der Gemeinschaft" zusatz={verbraucht ? `${fmt(r.bezugKwh)} kWh im Jahr` : "nur Erzeugung"}><Zahl wert={r.quotePct} stellen={0} suffix=" %" /></Kennzahl>
62	            <Kennzahl icon={Zap} label="Vorteil je kWh" zusatz="Energie + Netz + Abgabe">{verbraucht ? `${fmt(r.vorteilJeKwhCt, 2)} ct` : "–"}</Kennzahl>
63	            <Kennzahl icon={Leaf} label="CO₂ (rechnerisch)" zusatz="UBA-Faktor, AT eher niedriger"><Zahl wert={r.co2Kg} suffix=" kg" /></Kennzahl>
64	          </div>
65	          <ul className="mt-5 space-y-3 rounded-2xl p-4 ring-1 ring-ink-200/70" aria-label="Zusammensetzung des Vorteils">
66	            {r.teile.map((t) => (
67	              <li key={t.id}>
68	                <div className="flex justify-between gap-3 text-[13.5px]"><span className="text-ink-700">{t.label}</span><span className="ov-num font-semibold text-ink-900">{euro(t.eur)}</span></div>
69	                <div className="mt-1 h-2 rounded-full bg-ink-100"><div className={t.id === "erzeuger" ? "h-2 rounded-full bg-sun-400" : t.id === "netz" ? "h-2 rounded-full bg-navy-600" : "h-2 rounded-full bg-ov-500"} style={{ width: `${Math.max(2, (Math.abs(t.eur) / max) * 100)}%` }} /></div>
70	              </li>
71	            ))}
72	            {erzeugt && <li className="flex items-center gap-2 text-[12.5px] text-ink-500"><Sun aria-hidden="true" className="h-3.5 w-3.5 text-sun-500" />{fmt(r.eingebrachtKwh)} kWh Ihres Überschusses nutzt die Gemeinschaft (ca. {fmt(r.nutzungsgradPct * 0.85)} %).</li>}
73	          </ul>
74	          <div className="mt-4 space-y-2.5">
75	            <Hinweis ton={r.regel.status === "gesichert" ? "neutral" : "warnung"} icon={Info}>Netzentgelt: {r.regel.text}{r.regel.abgabenBefreit ? "; Elektrizitätsabgabe entfällt für Gemeinschaftsstrom" : ""}. Quelle: {r.regel.quelle}.</Hinweis>
76	            {r.hinweise.map((h) => <Hinweis key={h.id} ton={h.id === "negativ" ? "warnung" : "neutral"} icon={h.id === "negativ" ? AlertTriangle : Info}>{h.text}</Hinweis>)}
77	          </div>
78	          <div className="mt-7 flex flex-col gap-3 border-t border-ink-100 pt-6 sm:flex-row sm:items-center sm:justify-between">
79	            <p className="max-w-md text-[13px] leading-relaxed text-ink-500">Näherung für eine erste Einschätzung, netto. Maßgeblich sind die Viertelstundenwerte Ihres Netzbetreibers und das Preisblatt Ihrer Gemeinschaft. Typisch sind 50–200 € im Jahr je Haushalt.</p>
80	            <Button href={ctaHref} size="lg" pfeil className="shrink-0">Gemeinschaft finden</Button>
81	          </div>
82	        </>
83	      }
84	    />
85	  );
86	}
