import { cn } from "./cn";

/**
 * Fortschrittsring (Quote, Auslastung, Profil-Vollständigkeit).
 * Server-Komponente; der Ring läuft beim Einscrollen ein.
 *
 * wert, max (Standard 100); groesse in px; staerke = Linienbreite
 * ton: marke | navy | warn | danger | auto (≥ 80 grün, ≥ 50 hellgrün, sonst Sonne)
 * dunkel: auf Navy-Flächen
 * label: Zugänglicher Name (Pflicht, wenn kein sichtbarer Kontext)
 * children: eigener Inhalt in der Mitte (sonst Prozentwert)
 */
const TON = { marke: "#669933", navy: "#003473", warn: "#c98500", danger: "#b8352a", hell: "#aed083" };

export default function FortschrittsRing({ wert = 0, max = 100, groesse = 72, staerke = 7, ton = "auto", dunkel = false, label = "Fortschritt", sofort = false, className, children }) {
  const anteil = Math.max(0, Math.min(1, (Number(wert) || 0) / (max || 100)));
  const prozent = Math.round(anteil * 100);
  const farbe =
    ton === "auto" ? (prozent >= 80 ? (dunkel ? TON.hell : TON.marke) : prozent >= 50 ? "#8cba58" : "#f5a70f") : TON[ton] || TON.marke;
  const r = (groesse - staerke) / 2;
  const c = groesse / 2;
  return (
    <span
      suppressHydrationWarning
      role="progressbar"
      aria-valuemin={0}
      aria-valuemax={max}
      aria-valuenow={Number(wert) || 0}
      aria-label={label}
      className={cn("relative inline-flex shrink-0 items-center justify-center", sofort ? "ov-sofort" : "ov-reveal", className)}
      data-dir={sofort ? undefined : "ohne"}
      style={{ width: groesse, height: groesse }}
    >
      <svg width={groesse} height={groesse} viewBox={`0 0 ${groesse} ${groesse}`} aria-hidden="true" className="-rotate-90">
        <circle cx={c} cy={c} r={r} fill="none" stroke={dunkel ? "rgba(255,255,255,0.12)" : "#eef0f4"} strokeWidth={staerke} />
        {anteil > 0 && (
          <circle
            cx={c}
            cy={c}
            r={r}

/** Überschrift des Ergebnisbereichs mit Status-Plakette */
export function ErgebnisKopf({ titel = "Ihr Ergebnis", plakette }) {
  return (
    <div className="flex flex-wrap items-center justify-between gap-3">
      <h2 className="font-display text-[22px] font-extrabold tracking-tight text-ink-900 md:text-[26px]">{titel}</h2>
      {plakette && (
        <span className="inline-flex items-center gap-2 rounded-full bg-ov-50 px-3 py-1 text-[12.5px] font-semibold text-ov-800 ring-1 ring-ov-200">
          <span className="h-1.5 w-1.5 rounded-full bg-ov-500" aria-hidden="true" />
          {plakette}
        </span>
      )}
    </div>
  );
}

/** Hinweiszeile im Ergebnis (neutral | warnung | gut) – blendet beim Erscheinen sanft ein */
export function Hinweis({ ton = "neutral", icon: Icon, children, className }) {
  const toene = {
    neutral: "bg-ink-50 text-ink-700 ring-ink-200/70",
    warnung: "bg-warn-50 text-ink-800 ring-warn-200",
    gut: "bg-success-50 text-ink-800 ring-success-200",
  };
  return (
    <p className={cn("animate-ov-einblenden flex items-start gap-2.5 rounded-2xl px-4 py-3 text-[13.5px] leading-relaxed ring-1", toene[ton], className)}>
      {Icon && <Icon aria-hidden="true" className={cn("mt-0.5 h-4 w-4 shrink-0", ton === "warnung" ? "text-warn-600" : ton === "gut" ? "text-ov-600" : "text-ink-500")} />}
      <span className="min-w-0">{children}</span>
    </p>
  );
}

