                </div>
              </li>
              <li className="flex items-baseline justify-between gap-3 border-t border-ink-200 pt-3 font-display text-[15px] font-bold text-ink-900">
                <span>{r.nettoEur < 0 ? "Nachteil netto" : "Vorteil netto"}<span className="sr-only">: </span></span>
                <span className={cn("ov-num", r.nettoEur < 0 && "text-danger-700")}>{euro(r.nettoEur)}</span>
              </li>
            </ul>
            {erzeugt && (
              <p className="mt-3 flex items-start gap-2 text-[12.5px] leading-snug text-ink-500">
                <Sun aria-hidden="true" className="mt-0.5 h-3.5 w-3.5 shrink-0 text-sun-500" />
                <span>{fmt(r.eingebrachtKwh)} kWh {vorstand ? "des" : "Ihres"} Überschusses nutzt die Gemeinschaft (ca. {fmt(r.nutzungsgradPct * 0.85)} %).</span>
              </p>
            )}
          </div>

          <div className="mt-4 space-y-2.5">
            <Hinweis ton={gesichert ? "neutral" : "warnung"} icon={gesichert ? Info : AlertTriangle}>
              {!gesichert && <strong className="font-semibold">Noch nicht gesichert: </strong>}
              Netzentgelt: {r.regel.text}{r.regel.abgabenBefreit ? "; Elektrizitätsabgabe entfällt für Gemeinschaftsstrom" : ""}. Quelle: {r.regel.quelle}.
            </Hinweis>
            {r.hinweise.map((h) => (
              <Hinweis key={h.id} ton={h.id === "negativ" ? "warnung" : "neutral"} icon={h.id === "negativ" ? AlertTriangle : Info}>
                {h.id === "negativ" && <strong className="font-semibold">Achtung: </strong>}
                {h.text}
              </Hinweis>
            ))}
          </div>

          <div className="mt-7 flex flex-col gap-4 border-t border-ink-100 pt-6 lg:flex-row lg:items-end lg:justify-between">
            <p className="max-w-md text-[13px] leading-relaxed text-ink-500">Erste Einschätzung, netto. Maßgeblich sind die Viertelstundenwerte {vorstand ? "des" : "Ihres"} Netzbetreibers und das Preisblatt {vorstand ? "der" : "Ihrer"} Gemeinschaft.</p>
            <div className="flex flex-col gap-2 lg:items-end">
              <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap">
                {zweitCta?.href && zweitCta?.label && <Button href={zweitCta.href} size="lg" variant="secondary" className="shrink-0">{zweitCta.label}</Button>}
                <Button href={ctaHref} size="lg" pfeil className="shrink-0">{ctaLabel}</Button>
              </div>
              {ctaHinweis && <p className="text-[12.5px] text-ink-500">{ctaHinweis}</p>}
            </div>
          </div>
        </>
      }
    />
  );
}

